// vbnoGetter matches base.Bucket's GetMaxVbno. Used instead of base.Bucket directly to avoid an
// import cycle (base already imports sgtest).
type vbnoGetter interface {
	GetMaxVbno(ctx context.Context) (uint16, error)
}

