// docIDsForCount returns the doc ID table for numVBuckets (32, 64, 100, 128 or 1024), failing the
// test if numVBuckets isn't one of those.
func docIDsForCount(t testing.TB, numVBuckets uint16) map[uint16][]string {
	var docIDs map[uint16][]string
	switch numVBuckets {
	case 32:
		docIDs = docIDsFor32VBuckets
	case 64:
		docIDs = docIDsFor64VBuckets
	case 100:
		docIDs = docIDsFor100VBuckets
	case 128:
		docIDs = docIDsFor128VBuckets
	case 1024:
		docIDs = docIDsFor1024VBuckets
	default:
		require.Fail(t, fmt.Sprintf("VBucketDocIDs: no pre-computed doc IDs for vBucket count %d", numVBuckets))
	}
	return docIDs
}

// VBucketDocIDs returns numDocs (<= docIDsPerVBucket) doc IDs hashing to vBucketID, for bucket's
// actual vBucket count.
func VBucketDocIDs(t testing.TB, bucket vbnoGetter, vBucketID uint16, numDocs int) []string {
	require.GreaterOrEqual(t, numDocs, 1, "VBucketDocIDs: numDocs must be at least 1")
	require.LessOrEqual(t, numDocs, docIDsPerVBucket, "VBucketDocIDs: numDocs %d exceeds the %d pre-computed doc IDs per vBucket", numDocs, docIDsPerVBucket)
	numVBuckets, err := bucket.GetMaxVbno(context.Background())
	require.NoError(t, err)

	docIDs := docIDsForCount(t, numVBuckets)
	ids, ok := docIDs[vBucketID]
	require.True(t, ok, "VBucketDocIDs: no pre-computed doc IDs for vBucket %d with vBucket count %d", vBucketID, numVBuckets)
	require.GreaterOrEqual(t, len(ids), numDocs, "VBucketDocIDs: only %d pre-computed doc IDs for vBucket %d with vBucket count %d, need %d", len(ids), vBucketID, numVBuckets, numDocs)
	return ids[:numDocs]
}

// DocPerVBucket returns one doc ID per reachable vBucket, keyed by vBucket number -- useful for
// tests that need a checkpoint on every vBucket.
func DocPerVBucket(t testing.TB, bucket vbnoGetter) map[uint16]string {
	numVBuckets, err := bucket.GetMaxVbno(context.Background())
	require.NoError(t, err)
	docIDs := docIDsForCount(t, numVBuckets)
	result := make(map[uint16]string, len(docIDs))
	for vBucket, ids := range docIDs {
		require.NotEmpty(t, ids, "no pre-computed doc IDs for vBucket %d with vBucket count %d", vBucket, numVBuckets)
		result[vBucket] = ids[0]
	}
	return result
}
